import {makePatternRound,renderPattern,patternFamilies} from '../patterns.js';import {gameFrame,roundFlow} from '../ui.js';
export function mountGame(root,c){const flow=roundFlow(root,c);let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function next(){flow.next();const r=makePatternRound(c.difficulty,patternFamilies[(flow.round-1)%patternFamilies.length]),selected=new Set();const area=gameFrame(root,'Find the exact copies','Match the color order and small details. Rotation and mirror flips do not change a match.');area.innerHTML=`<div class="pattern-reference"><div class="reference-pattern">${renderPattern(r.target)}</div><div><strong>Match this pattern</strong><p>Find all ${r.answers.length} copies.<br>Look closely at the layers and details.</p><button class="motion-toggle" aria-pressed="${paused}">${paused?'Resume motion':'Pause motion'}</button></div></div><div class="pattern-board ${paused?'motion-paused':''}" style="--pattern-cols:${c.difficulty==='easy'?3:c.difficulty==='hard'?4:3}">${r.items.map((x,i)=>`<button class="pattern-tile" data-i="${i}" aria-pressed="false" aria-label="Pattern ${i+1}"><span class="rotating-pattern" style="--start-angle:${x.rotation}deg;--spin-time:${(c.difficulty==='hard'?4:c.difficulty==='easy'?9:6)+(i%4)}s;--spin-direction:${i%2?'reverse':'normal'}"><span class="flipping-pattern" style="--flip-time:${5+i%3}s;--flip-delay:${-i*.7}s">${renderPattern(x)}</span></span><span class="pattern-index">${i+1}</span><span class="pattern-check" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="m4 10 4 4 8-8"/></svg></span></button>`).join('')}</div><div class="answer-row"><span id="selection-count">0 selected / ${r.answers.length} needed</span><button class="primary" id="check-patterns">Compare selection</button></div>`;area.querySelector('.motion-toggle').onclick=e=>{paused=!paused;area.querySelector('.pattern-board').classList.toggle('motion-paused',paused);e.currentTarget.textContent=paused?'Resume motion':'Pause motion';e.currentTarget.setAttribute('aria-pressed',paused);};area.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;selected.has(i)?selected.delete(i):selected.add(i);b.setAttribute('aria-pressed',selected.has(i));area.querySelector('#selection-count').textContent=`${selected.size} selected / ${r.answers.length} needed`;});area.querySelector('#check-patterns').onclick=()=>{const correct=r.answers.length===selected.size&&r.answers.every(i=>selected.has(i));flow.answer(correct,`Exact copies: ${r.answers.map(i=>i+1).join(', ')}. The others change a color’s position or a small detail.`,next);area.querySelector('.pattern-board').classList.add('motion-paused');r.answers.forEach(i=>area.querySelector(`[data-i="${i}"]`).classList.add('solution-tile'));};}next();return {dispose(){}};}
